function baseSave(B) { try { const u = uCur(); if (!(B && B.E > 0 && B.usedS != null)) return; const nb = { month: u.month, E: B.E, remainGB: B.remainGB, baseAt: B.baseAt || '', mark: (u.total.tether || 0) - B.usedS, at: kst() }; if (!BASE || BASE.month !== nb.month || BASE.remainGB !== nb.remainGB || BASE.baseAt !== nb.baseAt || Math.abs((BASE.mark || 0) - nb.mark) > 50 * 1048576) { BASE = nb; fs.writeFileSync(BASE_F(), JSON.stringify(nb)); } } catch (e) {} }
