function days7() { const u = uCur(); const out = []; for (let i = 0; i < 7; i++) { const k = day(Date.now() - i * 864e5); if (k.slice(0, 7) !== u.month) break; const d = u.days[k]; out.push({ k, t: d ? d.tether || 0 : 0, w: d ? d.wifi || 0 : 0 }); } return out; } let PEND_T = 0; const MET = []; function addTetherPend(n) { PEND_T += n; }
function meterAdd(q) { const m = Math.max(0, +q.main || 0), g = Math.max(0, +q.gen || 0); const J = {}; /* (1.6.2) 일별 몫(벤치마킹·시장 지표…)도 — jobs=bench:123,market:45 */ String(q.jobs || '').split(',').forEach((x) => { const [k, v] = x.split(':'); const kk = String(k || '').replace(/[^A-Za-z0-9_]/g, '').slice(0, 30); if (kk && +v > 0) J[kk] = (J[kk] || 0) + +v; }); if (m + g > 0) MET.push({ at: Date.now(), main: m, gen: g, jobs: J }); }
function meterSplit() { if (!PEND_T) { while (MET.length && Date.now() - MET[0].at > 45e3) MET.shift(); return; } const n = PEND_T; PEND_T = 0; while (MET.length && Date.now() - MET[0].at > 45e3) MET.shift(); const fresh = MET; /* 최근 45초 안의 알림으로 몫을 나눔(알림은 30초마다 — 그 사이 10초 창들도 같은 몫으로) */ const cm = fresh.reduce((a, x) => a + x.main, 0), cg = fresh.reduce((a, x) => a + x.gen, 0);
  const add = (k, v) => { if (!v) return; const u = uCur(); const d = day(); const D = (u.days[d] = u.days[d] || { tether: 0, wifi: 0, groups: {}, blocked: 0 }); D.tiers = D.tiers || {}; D.tiers[k] = (D.tiers[k] || 0) + v; u.total.tiers = u.total.tiers || {}; u.total.tiers[k] = (u.total.tiers[k] || 0) + v; uDirty = true; };
  if (cm + cg <= 0) return add('other', n); const a = Math.round(n * cm / (cm + cg)); add('main', a); add('gen', n - a);
  /* (1.6.2) 📶 일별 실제 바이트 — 같은 알림의 글자 몫대로(벤치마킹이 실제로 얼마나 썼는지) */ const cj = {}; fresh.forEach((x) => { for (const [k, v] of Object.entries(x.jobs || {})) cj[k] = (cj[k] || 0) + v; }); const tj = Object.values(cj).reduce((p, v) => p + v, 0); if (tj > 0) { const u = uCur(); const d = day(); const D = u.days[d]; D.jobs = D.jobs || {}; u.total.jobs = u.total.jobs || {}; for (const [k, v] of Object.entries(cj)) { const b = Math.round(n * v / (cm + cg)); D.jobs[k] = (D.jobs[k] || 0) + b; u.total.jobs[k] = (u.total.jobs[k] || 0) + b; } uDirty = true; } }
function addBlocked(host, why) { const u = uCur(); const d = day(); const D = (u.days[d] = u.days[d] || { tether: 0, wifi: 0, groups: {}, blocked: 0 }); D.blocked = (D.blocked || 0) + 1; D.lastBlocked = { host, why, at: kst() }; uDirty = true; }
let uDirty = false; function uSave() { if (!U) return; try { const p = uPath(U.month); fs.writeFileSync(p + '.tmp', JSON.stringify(U)); fs.renameSync(p + '.tmp', p); uDirty = false; } catch (e) { log('사용량 저장 실패', e.message); } }
setInterval(() => { if (uDirty) uSave(); }, 30e3);
/* (1.5.0) 한 달 상한 = 등록한 휴대폰(쓰지 않음 빼고) 상한의 합 — 아직 휴대폰이 없으면 예전처럼 capGB · 수집기 📶 몫이 이 합으로 나눔 · 막힘은 '지금 쓰는 휴대폰'의 상한으로(gate) */
/* (1.8.1) 정범님 10/23 22:35: 10월은 10/23부터 월말까지 약 60GB — 그 전(요금제 바꾼 날~10/22)에 쓴 양 + 60GB를 이달 상한으로(예전 셈 120÷31×11 = 42.58GB는 너무 일찍 막음) · 설정 monthOvr로 바꿀 수 있음 */
const MONTH_OVR = { '2026-10': { from: '2026-10-23', gb: 60 } };
const ovrGB = () => { const m = uCur().month; const o = (CFG.monthOvr || {})[m] || MONTH_OVR[m]; if (!o || !(+o.gb > 0) || !/^\d{4}-\d\d-\d\d$/.test(String(o.from || ''))) return null; const s = planOn() || m + '-01'; const pre = Object.entries(uCur().days || {}).filter(([k]) => k >= s && k < o.from).reduce((a, [, v]) => a + (+(v || {}).tether || 0), 0) - (planOn() ? +CFG.planPre || 0 : 0); return Math.round((Math.max(0, pre) / GiB + +o.gb) * 100) / 100; };
const capGBTotal = () => { const ov = ovrGB(); if (ov != null) return ov; if (+CFG.planGB > 0) { const s = planOn(); if (s) { const m = uCur().month; const dim = new Date(Date.UTC(+m.slice(0, 4), +m.slice(5, 7), 0)).getUTCDate(); return Math.round(+CFG.planGB / dim * (dim - +s.slice(8, 10) + 1) * 100) / 100; } return +CFG.planGB; } const P = Object.values(phonesCfg()).filter((r) => r && !r.off); return P.length ? P.reduce((a, r) => a + (+r.capGB || 0), 0) : +CFG.capGB || 48; }; /* (1.7.1) 요금제 = 한 달 planGB · 바꾼 달은 planGB ÷ 그달 날 수 × (바꾼 날부터 말일까지 날 수) — 정범님 10/21 */
const capBytes = () => Math.round(capGBTotal() * GiB * Math.min(100, Math.max(50, +CFG.capStopPct || 99)) / 100);
const capped = () => !ST.tether.viaWifi && (tetherCapUsed() >= capBytes() || (!!ST.tether.phone && phoneCapped(ST.tether.phone)));
/* 연결마다 늘어난 만큼만 더함(오래 열린 연결도 10초마다) */
const live = new Set(); function track(sock, route, group, phone) { const e = { sock, route, group, phone: phone || null, r: 0, w: 0 }; live.add(e); const flush = () => { const r = sock.bytesRead || 0, w = sock.bytesWritten || 0; addBytes(route, group, (r - e.r) + (w - e.w), e.phone); e.r = r; e.w = w; }; e.flush = flush; sock.once('close', () => { flush(); live.delete(e); }); }
