  if (u.pathname === '/bud') { try { const j = JSON.parse(u.searchParams.get('d') || '{}'); BUDI = { at: Date.now(), ...Object.fromEntries(Object.entries(j).filter(([k, v]) => /^[a-zA-Z]{1,12}$/.test(k) && (typeof v === 'number' || typeof v === 'boolean' || (typeof v === 'string' && v.length < 40)))) }; baseSave(BUDI); } catch (e) {} res.writeHead(200, { ...H, 'Content-Type': 'application/json; charset=utf-8' }); return res.end('{"ok":true}'); } /* (1.6.2) 수집기가 계산한 '통신사 기준 남은 양·오늘 몫'(표시용) */
